package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.persistence.mapper.*;import java.io.*;import java.time.*;import java.util.*;
public final class ModelEligibilityAuthority {
 private final ModelConfigurationService models;private final ModelEligibilityMapper mapper;private final ConnectionVerificationService connections;private final ApprovedCredentialAuthority credentials;private final ResourceReadAuthority resources;private final PermissionMapper permissions;private final PermissionAuthority grants;private final RuntimeGovernanceSchema schema;private final PermissionSchema json;private final SchemaCatalogue catalogue;private final ModelPolicyBasisAuthority policyBasis;private final com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities;
 public ModelEligibilityAuthority(ModelConfigurationService models,ModelEligibilityMapper mapper,ConnectionVerificationService connections,ApprovedCredentialAuthority credentials,ResourceReadAuthority resources,PermissionMapper permissions,PermissionAuthority grants,RuntimeGovernanceSchema schema,PermissionSchema json,SchemaCatalogue catalogue,ModelPolicyBasisAuthority policyBasis,com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities){this.identities=identities;this.models=models;this.mapper=mapper;this.connections=connections;this.credentials=credentials;this.resources=resources;this.permissions=permissions;this.grants=grants;this.schema=schema;this.json=json;this.catalogue=catalogue;this.policyBasis=policyBasis;}
 public final class Verified {
  private final EnterpriseAccess.Admission admission;private final String model,purpose,project,digest;private final ModelEligibilityBinding binding;private final ModelConfigurationProtocol.Definition definition;private final List<PermissionProtocol.GrantRow> witnesses;
  private Verified(EnterpriseAccess.Admission a,String model,String purpose,String project,ModelEligibilityBinding binding,ModelConfigurationProtocol.Definition definition,List<PermissionProtocol.GrantRow> witnesses,String digest){this.admission=a;this.model=model;this.purpose=purpose;this.project=project;this.binding=binding;this.definition=definition;this.witnesses=List.copyOf(witnesses);this.digest=digest;}
  public String modelRevision(){return model;}public String configId(){return binding.config_id();}public String connectionVerificationId(){return binding.connection_verification_id();}public String credentialReferenceId(){return binding.credential_reference_id();}public String credentialRevision(){return binding.credential_revision();}public String priceVersion(){return binding.price_version();}public String dataPolicyVersion(){return binding.data_policy_version();}public String contentSha256(){return binding.config_content_sha256();}public List<PermissionProtocol.Basis> dependencyVersions(){return List.of(new PermissionProtocol.Basis(model,binding.config_content_sha256()),definition.price_basis(),definition.data_policy().policy_basis());}public ModelEligibilityBinding safeReplayBinding(){return binding;}public List<PermissionProtocol.GrantRow> authorizations(){return witnesses;}
  public void requireDataUse(String classification,String region,boolean training){if(!definition.data_policy().allowed_classifications().contains(classification)||!definition.data_policy().allowed_regions().contains(region)||training&&!definition.data_policy().allow_training())deny(ErrorCode.ACCESS_DENIED);}
  public SchemaCatalogue.ValidatedPayload requireParameters(JsonNode parameters)throws IOException{var output=parameters.required("max_output_tokens");if(!output.isIntegralNumber()||output.bigIntegerValue().compareTo(new java.math.BigInteger(definition.limits().max_output_tokens()))>0||parameters.required("stop").size()>definition.limits().stop_limit()||!parameters.required("temperature").isNull()&&!definition.limits().temperature_enabled()||!parameters.required("reasoning_effort").isNull()&&!definition.limits().reasoning_efforts().contains(parameters.required("reasoning_effort").textValue()))deny(ErrorCode.MODEL_POLICY_INCOMPLETE);return catalogue.bindPublished(definition.request_parameter_schema_ref(),definition.request_parameter_schema_sha256(),ContentReadAuthorization.canonicalBytes(parameters));}
  public void requireUnchanged()throws IOException{if(!digest.equals(require(admission,model,purpose,project).digest))deny(ErrorCode.SCOPE_STALE);}
 }
 public Verified require(EnterpriseAccess.Admission a,String model,String purpose,String targetProject)throws IOException{
  if(!Set.of("TASK_CREATION","PLAN_MAINTENANCE","RUN_CREATION","AGENT_PUBLICATION").contains(purpose))deny(ErrorCode.ACCESS_DENIED);
  var fixed=models.requireCurrentExternal(a,model,purpose,targetProject);var definition=(ModelConfigurationProtocol.Definition)fixed.definition();var row=one(mapper.model(ModelEligibilityAuthority.parameters("modelRevision",model)));JsonNode stored=verify(row);
  if(!row.tenantId().equals(a.context().tenant_id())||!row.modelRevision().equals(model)||!row.configId().equals(fixed.config_id())||!Objects.equals(row.projectId(),fixed.project_id())||!"ENABLED".equals(row.status()))deny(ErrorCode.ACCESS_DENIED);
  var evidence=new com.fasterxml.jackson.databind.ObjectMapper().treeToValue(stored.required("request").required("data_policy_evidence"),ModelPolicyBasisAuthority.Evidence.class);var dataPolicy=policyBasis.require(a,definition.data_policy().policy_basis(),evidence);
  var connection=connections.requirePassed(a,row.verificationId(),model,purpose,targetProject);var credential=credentials.require(a.context().tenant_id(),definition.credential_reference_id(),definition.credential_revision(),definition.provider(),definition.base_url());
  var safe=binding(fixed,row.verificationId());if(!json.tree(safe).equals(stored.required("binding")))deny(ErrorCode.CONTENT_MISMATCH);
  if(!definition.price_basis().version_id().equals(connection.priceVersion()))deny(ErrorCode.CONTENT_MISMATCH);
  String actor=stored.required("approved_by").textValue();var member=one(permissions.targetMember(actor));var identity=one(permissions.targetBinding(actor));var now=permissions.databaseTime();if(!member.userId().equals(actor)||!member.tenantId().equals(a.context().tenant_id())||!"ACTIVE".equals(member.status())||member.validFrom().isAfter(now)||member.validTo()!=null&&!member.validTo().isAfter(now)||!identity.userId().equals(actor)||!"ACTIVE".equals(identity.status()))deny(ErrorCode.ACCESS_DENIED);
  if(!Set.of("local","oidc").contains(identity.mode())||"local".equals(identity.mode())&&!actor.equals(identity.localUserId())||"oidc".equals(identity.mode())&&identity.localUserId()!=null||!identities.active(new com.ruoyi.medical.identity.AuthenticatedIdentityBinding.View(identity.mode(),identity.userId(),identity.issuer(),identity.subject())))deny(ErrorCode.ACCESS_DENIED);
  var grant=one(permissions.currentGrant(stored.required("approval_grant").required("grant_id").textValue()));var scope=new PermissionProtocol.Scope(a.context().tenant_id(),fixed.project_id(),"CONFIGURATION",fixed.config_id());grants.requireResource(scope,actor,identity.mode(),"model.enable","MODEL_ENABLEMENT",List.of(grant),now);if(!grant.revision().toString().equals(stored.required("approval_grant").required("revision").textValue()))deny(ErrorCode.SCOPE_STALE);
  var read=resources.require(a,scope,"configuration.read",purpose);credential.requireCurrent();connection.requireUnchanged();dataPolicy.requireCurrent();var witnesses=new ArrayList<PermissionProtocol.GrantRow>();witnesses.add(read);witnesses.add(grant);witnesses.addAll(dataPolicy.authorizations());return new Verified(a,model,purpose,targetProject,safe,definition,witnesses,schema.hash(Map.of("fixed",stored,"status",row.status(),"revision",row.revision(),"grants",witnesses,"credential",credential.binding())));
 }
 ModelEligibilityBinding binding(ModelConfigurationProtocol.Fixed fixed,String verification)throws IOException{var d=(ModelConfigurationProtocol.Definition)fixed.definition();return new ModelEligibilityBinding("1.0.0",d.provider(),d.model_id(),d.model_version(),fixed.model_config_revision(),fixed.config_id(),schema.hash(fixed),verification,d.credential_reference_id(),d.credential_revision(),d.price_basis().version_id(),d.data_policy().policy_basis().version_id(),d.data_policy().allowed_classifications(),d.data_policy().allowed_regions(),d.data_policy().allow_training());}
 JsonNode verify(ModelEligibilityMapper.Row r)throws IOException{var fixed=schema.validate("ModelEnableFixed",schema.read(r.fixedJson()));if(!r.tenantId().equals(fixed.required("tenant_id").textValue())||!r.eligibilityId().equals(fixed.required("eligibility_id").textValue())||!r.createdBy().equals(fixed.required("approved_by").textValue())||!Instant.parse(r.createdAt()).equals(Instant.parse(fixed.required("approved_at").textValue()))||!schema.hash(fixed).equals(r.contentHash())||!schema.hash(fixed.required("request")).equals(r.requestHash())||!schema.manifest().equals(r.manifest())||!"1.0.0".equals(r.schemaVersion()))deny(ErrorCode.CONTENT_MISMATCH);
  var request=fixed.required("request");var receipt=schema.validate("ModelEnableReceipt",schema.read(r.receiptJson()));if(!TenantScope.requireCurrent().tenantId().equals(r.tenantId())||!"ENABLED".equals(r.status())||!"1".equals(r.revision())||!r.modelRevision().equals(request.required("model_config_revision").textValue())||!r.verificationId().equals(request.required("connection_verification_id").textValue())||!r.modelRevision().equals(fixed.required("binding").required("model_config_revision").textValue())||!r.configId().equals(fixed.required("binding").required("config_id").textValue())||!r.verificationId().equals(fixed.required("binding").required("connection_verification_id").textValue())||!r.eligibilityId().equals(receipt.required("eligibility_id").textValue())||!r.modelRevision().equals(receipt.required("model_config_revision").textValue())||!r.operationId().equals(receipt.required("operation_id").textValue())||!r.contentHash().equals(receipt.required("content_sha256").textValue())||!r.requestHash().equals(receipt.required("request_body_sha256").textValue()))deny(ErrorCode.CONTENT_MISMATCH);
  var v=values(r);if(!r.contentHash().equals(one(mapper.registry(v)))||!schema.read(one(mapper.operation(v))).equals(schema.read(r.receiptJson()))||!schema.read(one(mapper.audit(v))).equals(schema.read(r.receiptJson()))||!schema.read(one(mapper.event(v))).equals(schema.read(r.receiptJson())))deny(ErrorCode.CONTENT_MISMATCH);return fixed;}
 static Map<String,Object> parameters(String key,Object value){return Map.of("userId",TenantScope.requireCurrent().subjectId(),key,value);}
 static Map<String,Object> values(ModelEligibilityMapper.Row r){var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("eligibilityId",r.eligibilityId());v.put("projectId",r.projectId());v.put("modelRevision",r.modelRevision());v.put("creator",r.createdBy());v.put("operationId",r.operationId());v.put("key",r.key());v.put("requestHash",r.requestHash());v.put("manifest",r.manifest());v.put("classification",r.classification());v.put("auditId",r.auditId());v.put("eventId",r.eventId());return v;}
 static <T>T one(List<T> rows){if(rows.size()!=1)deny(ErrorCode.CONTENT_MISMATCH);return Objects.requireNonNull(rows.get(0));}static void deny(ErrorCode code){throw new TenantAccessException(code);}
}
